DROP TRIGGER tasks_revision_insert;
DROP TRIGGER tasks_revision_update;
DROP TRIGGER tasks_revision_delete;
DROP INDEX tasks_project_status_sort;
CREATE TABLE tasks_archived_status (id TEXT PRIMARY KEY, identifier TEXT NOT NULL UNIQUE, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK (status IN ('backlog', 'todo', 'in_progress', 'in_review', 'blocked', 'done', 'canceled', 'archived')), priority TEXT NOT NULL CHECK (priority IN ('none', 'urgent', 'high', 'medium', 'low')), labels TEXT NOT NULL DEFAULT '[]', sort_order REAL NOT NULL, thread_id TEXT, creator_type TEXT NOT NULL CHECK (creator_type IN ('user', 'agent')), creator_id TEXT NOT NULL, creator_name TEXT NOT NULL, creator_avatar_url TEXT, assignee_type TEXT NOT NULL CHECK (assignee_type IN ('user', 'agent')), assignee_id TEXT NOT NULL, assignee_name TEXT NOT NULL, assignee_avatar_url TEXT, workflow_id TEXT, development_context_type TEXT CHECK (development_context_type IS NULL OR development_context_type IN ('branch', 'worktree')), development_branch TEXT, due_date TEXT, recurrence_interval INTEGER, recurrence_unit TEXT, archived_at TEXT, version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
INSERT INTO tasks_archived_status (id, identifier, project_id, title, description, status, priority, labels, sort_order, thread_id, creator_type, creator_id, creator_name, creator_avatar_url, assignee_type, assignee_id, assignee_name, assignee_avatar_url, workflow_id, development_context_type, development_branch, due_date, recurrence_interval, recurrence_unit, archived_at, version, created_at, updated_at) SELECT id, identifier, project_id, title, description, CASE WHEN archived_at IS NOT NULL THEN 'archived' ELSE status END, priority, labels, sort_order, thread_id, creator_type, creator_id, creator_name, creator_avatar_url, assignee_type, assignee_id, assignee_name, assignee_avatar_url, workflow_id, development_context_type, development_branch, due_date, recurrence_interval, recurrence_unit, archived_at, version, created_at, updated_at FROM tasks;
DROP TABLE tasks;
ALTER TABLE tasks_archived_status RENAME TO tasks;
CREATE INDEX tasks_project_status_sort ON tasks(project_id, archived_at, status, sort_order, created_at);
CREATE TRIGGER tasks_revision_insert AFTER INSERT ON tasks BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER tasks_revision_update AFTER UPDATE ON tasks BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER tasks_revision_delete AFTER DELETE ON tasks BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
